sys_script_client.script:
function onLoad() {

    var parentCaseId = g_form.getValue('complaint_case');
    if (!parentCaseId) {
        return;
    }
    var taskAssignedTo = g_form.getValue('assigned_to');

	if (!taskAssignedTo) {
        var ga = new GlideAjax('MSSTrusteesCallUtils');
        ga.addParam('sysparm_name', 'validateAssigneeComp');
        ga.addParam('sysparm_task_assigned_to', g_user.userID);
        ga.addParam('sysparm_parent_id', parentCaseId);
        ga.getXML(handleResponse); // Use getXML with a callback function        
    } else {
        var ga = new GlideAjax('MSSTrusteesCallUtils');
        ga.addParam('sysparm_name', 'validateAssigneeComp');
        ga.addParam('sysparm_task_assigned_to', taskAssignedTo);
        ga.addParam('sysparm_parent_id', parentCaseId);
        ga.getXML(handleResponseIFAssigned);
    }

    // The callback function will handle the response
    function handleResponse(response) {
        var answer = response.responseXML.documentElement.getAttribute("answer");
        if (answer == 'true') {
            g_form.addErrorMessage('Maker and Checker can not be the same person.');
            g_form.setDisabled('u_stage', true);
        }
    }

    function handleResponseIFAssigned(res) {
        var answer = res.responseXML.documentElement.getAttribute("answer");
        if (answer == 'true') {
            g_form.addErrorMessage('Maker and Checker can not be the same person.');
            g_form.setDisabled('u_stage', true);
            g_form.clearValue('assigned_to');
            g_form.save();
        }
    }


}
